function get(name){const p=data[String(name||'')];return p?{...p}:null;}
function forDestination(d){if(!d)return [];const cities=NorthHotelData.cities();const country=d.type==='country'||d.name===d.country;const list=country?cities.filter(c=>c.country===d.country):cities.filter(c=>c.name===d.name);return list.map(c=>{const p=get(c.name);return p?{...p,name:c.name}:null;}).filter(Boolean).slice(0,6);}
